package dev.raf.radar;
import java.io.*;import java.util.*;import java.util.concurrent.atomic.AtomicLong;import org.json.*;import org.junit.*;import org.junit.rules.TemporaryFolder;import static org.junit.Assert.*;
public class ObservationQueueTest {
 @Rule public TemporaryFolder temp=new TemporaryFolder();
 @Test public void cadenceZeroOfflineRestartAndAccountIsolation()throws Exception{AtomicLong now=new AtomicLong(System.currentTimeMillis());File file=new File(temp.newFolder(),"queue.json");ObservationQueue q=new ObservationQueue(file,now::get);Point p=new Point("fixture","Never upload this name",55,61,false);assertTrue(q.capture(1,p,reading(0,now.get()),"0.1.33-alpha","Asia/Yekaterinburg"));now.addAndGet(299999);assertFalse(q.capture(1,p,reading(100,now.get()),"0.1.33-alpha","UTC"));now.incrementAndGet();assertTrue(q.capture(1,p,reading(200,now.get()),"0.1.33-alpha","UTC"));q=new ObservationQueue(file,now::get);assertEquals(2,q.batch(1).length());assertEquals(0,q.batch(2).length());assertFalse(DiagnosticJournal.read(file).contains("Never upload"));JSONArray ack=new JSONArray().put(q.batch(1).getJSONObject(0).getString("observationId"));q.acknowledge(ack);assertEquals(1,new ObservationQueue(file,now::get).batch(1).length());}
 @Test public void excludesGpsDisabledUnknownStaleAndExpiresQueue()throws Exception{AtomicLong now=new AtomicLong(System.currentTimeMillis());ObservationQueue q=new ObservationQueue(new File(temp.newFolder(),"queue.json"),now::get);Point p=new Point("fixture","Fixture",55,61,false);assertFalse(q.capture(1,p,reading(null,now.get()),"0.1.33-alpha","UTC"));assertFalse(q.capture(1,p,reading(10,now.get()-180001),"0.1.33-alpha","UTC"));p.dynamic=true;assertFalse(q.capture(1,p,reading(100,now.get()),"0.1.33-alpha","UTC"));p.dynamic=false;p.enabled=false;assertFalse(q.capture(1,p,reading(100,now.get()),"0.1.33-alpha","UTC"));p.enabled=true;assertTrue(q.capture(1,p,reading(100,now.get()),"0.1.33-alpha","UTC"));now.addAndGet(7L*86400000+1);assertEquals(0,q.batch(1).length());}
 static List<Store.Reading> reading(Integer rub,long at){return Collections.singletonList(new Store.Reading("econom",rub,null,at,"fixture"));}
}
